"""Jinja2 environment factory + custom filters.

The environment uses `ChoiceLoader` over the resolved layer roots so a template in
a later layer shadows the same relative path in an earlier one, while `extends`
across layers continues to work.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from jinja2 import ChoiceLoader, Environment, FileSystemLoader, StrictUndefined

from harness.compose.layers import Layer, existing_layers


def _to_yaml_filter(value: Any) -> str:
    """Render a Python value as inline YAML (compact, no document marker)."""
    from io import StringIO

    from ruamel.yaml import YAML

    yaml = YAML()
    yaml.default_flow_style = False
    yaml.indent(mapping=2, sequence=4, offset=2)
    buf = StringIO()
    yaml.dump(value, buf)
    return buf.getvalue().rstrip()


def _to_json_indent(value: Any, indent: int = 2) -> str:
    return json.dumps(value, indent=indent, sort_keys=True)


def _env_or_default(varname: str, default: str = "") -> str:
    """Render `${VARNAME:-DEFAULT}` for downstream config files (NOT runtime expansion)."""
    return f"${{{varname}:-{default}}}" if default else f"${{{varname}}}"


def _glob_or_empty(value: list[str] | None) -> list[str]:
    return value or []


def build_environment(layers: list[Layer]) -> Environment:
    """Build a Jinja2 Environment that searches the given layers in priority order
    (later layers in the list take precedence)."""
    layer_paths = [str(layer.root) for layer in existing_layers(list(reversed(layers)))]
    # Reversed so the latest-defined layer (highest precedence) is searched first.
    if not layer_paths:
        # Fallback: empty FileSystemLoader so render calls fail with a clear error
        loader = FileSystemLoader([])
    else:
        loader = ChoiceLoader([FileSystemLoader(p) for p in layer_paths])

    env = Environment(
        loader=loader,
        undefined=StrictUndefined,
        autoescape=False,
        keep_trailing_newline=True,
        trim_blocks=False,
        lstrip_blocks=False,
    )
    env.filters["to_yaml"] = _to_yaml_filter
    env.filters["to_json_indent"] = _to_json_indent
    env.filters["glob_or_empty"] = _glob_or_empty
    env.globals["env_or_default"] = _env_or_default
    return env


def render_template(
    env: Environment, relative_path: str, context: dict[str, Any]
) -> str:
    """Render a single template by its relative path within the layer roots."""
    template = env.get_template(relative_path)
    return template.render(**context)


def list_templates(layers: list[Layer], suffix: str = ".j2") -> list[str]:
    """Enumerate template relative paths across all layers (deduped, sorted).

    Files outside `suffix` are still returned (without rendering) so the writer can
    copy static assets verbatim.

    Paths always use forward slashes regardless of host OS — Jinja2's FileSystemLoader
    requires `/` separators in template names, and emitted output paths are then re-joined
    with the host OS separator at write time.
    """
    seen: set[str] = set()
    for layer in existing_layers(layers):
        if not layer.root.is_dir():
            continue
        for path in layer.root.rglob("*"):
            if not path.is_file() or _is_junk(path):
                continue
            rel = path.relative_to(layer.root).as_posix()
            seen.add(rel)
    return sorted(seen)


# OS/editor metadata that may sit inside a layer dir but is never emittable.
# These are not valid UTF-8 (e.g. .DS_Store), so reading them verbatim would
# crash the composer; skip them at the single enumeration point.
_JUNK_NAMES = frozenset({".DS_Store", "Thumbs.db", "desktop.ini"})


def _is_junk(path: Path) -> bool:
    return (
        path.name in _JUNK_NAMES
        or path.suffix == ".pyc"
        or "__pycache__" in path.parts
    )


def is_jinja_template(relative_path: str) -> bool:
    """Files ending in `.j2` are rendered; everything else is copied verbatim."""
    return relative_path.endswith(".j2")


def output_path_for(relative_path: str) -> str:
    """Strip the `.j2` suffix to get the emitted file path."""
    return relative_path[:-3] if relative_path.endswith(".j2") else relative_path
